def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    barrier = next((r for r, row in enumerate(grid) if row and all(x == 2 for x in row)), None)

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                out[r][c] = 2
            elif grid[r][c] == 4:
                nr = min(r + 1, h - 1)
                out[nr][c] = 4
                if barrier is not None and r == barrier - 2:
                    for d in range(1, h):
                        rr = nr - d
                        if rr < 0:
                            break
                        for cc in (c - d, c + d):
                            if 0 <= cc < w:
                                out[rr][cc] = 4
    return out
